const webhook = $('Webhook').first()?.json ?? {};
const requestedId = String(webhook.params?.public_id ?? webhook.public_id ?? '').trim();
const publicIdPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{5,79}$/;
const numericTelegramPattern = /^(?:\d{6,80}|\d+(?:[-_]\d+)+)$/;

function response(body, httpStatus = 200) {
  return [{ json: { response: body, http_status: httpStatus } }];
}

function extractImageUrls(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map((attachment) => (
      typeof attachment === 'string'
        ? attachment
        : attachment?.url
          ?? attachment?.signedUrl
          ?? attachment?.signed_url
          ?? attachment?.thumbnails?.small?.signedUrl
          ?? attachment?.thumbnails?.small?.signed_url
          ?? ''
    ))
    .filter((url) => /^https?:\/\//i.test(String(url)));
}

if (!publicIdPattern.test(requestedId) || numericTelegramPattern.test(requestedId)) {
  return response({ ok: false, error: 'not_found' }, 404);
}

const found = $input.all()
  .map(({ json }) => ({ json, fields: json.fields ?? json }))
  .find(({ fields }) => String(fields.public_id ?? fields['item-id'] ?? '') === requestedId);

if (!found) return response({ ok: false, error: 'not_found' }, 404);

const fields = found.fields;
const rawStatus = String(fields.status ?? 'hidden').toLowerCase();
if (!['available', 'completed', 'expired'].includes(rawStatus)) {
  return response({ ok: false, error: 'not_found' }, 404);
}

const expiresAt = fields.expires_at ?? null;
const expiresTimestamp = expiresAt ? new Date(String(expiresAt).replace(' ', 'T')).getTime() : NaN;
const status = rawStatus === 'available' && Number.isFinite(expiresTimestamp) && expiresTimestamp < Date.now()
  ? 'expired'
  : rawStatus;
const imageUrls = [...new Set([
  ...extractImageUrls(fields.photos),
  ...extractImageUrls(fields.Fotos),
  ...extractImageUrls(fields.fotos),
])];

const item = {
  id: fields.public_id ?? fields['item-id'] ?? requestedId,
  title: fields.title ?? '',
  description: fields.description ?? '',
  category: fields.category ?? 'Otros',
  zone: fields.zone ?? 'Valladolid',
  status,
  created_at: fields.created_at ?? fields.CreatedAt ?? null,
  updated_at: fields.updated_at ?? fields.UpdatedAt ?? null,
  expires_at: expiresAt,
  completed_at: fields.completed_at ?? null,
  image_url: fields.image_url || imageUrls[0] || null,
  image_urls: imageUrls,
  owner_display_name: fields.owner_display_name ?? 'Vecindad',
  owner_username: fields.owner_username || null,
  interest_count: Number(fields.interest_count ?? 0),
};

return response({ ok: true, item });
